use std::{env, fs, path::PathBuf};

fn main() {
    let directory = PathBuf::from("../doc/efun");
    println!("cargo:rerun-if-changed={}", directory.display());
    let mut files: Vec<_> = fs::read_dir(directory)
        .expect("efun documentation directory")
        .map(|entry| entry.expect("efun documentation file").path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "md"))
        .collect();
    files.sort();
    let mut code =
        String::from("fn documentation(name: &str) -> Option<&'static str> { match name {\n");
    for path in files {
        let name = path.file_stem().unwrap().to_string_lossy();
        let text = fs::read_to_string(&path).expect("UTF-8 efun documentation");
        code.push_str(&format!("{name:?} => Some({text:?}),\n"));
    }
    code.push_str("_ => None, } }\n");
    fs::write(
        PathBuf::from(env::var_os("OUT_DIR").unwrap()).join("efun_docs.rs"),
        code,
    )
    .expect("generated efun documentation");
}

impl Transaction {
    pub(crate) fn new(snapshot: Snapshot) -> Self {
        let version = snapshot.version();
        Self {
            snapshot,
            changeset: Changeset::new(version),
            effects: Vec::new(),
            pending_call_outs: Vec::new(),
            cancelled_call_outs: HashSet::new(),
            joinable: true,
            interrupted: None,
            compilation: diagnostics::CompilationTiming::default(),
            presence_revision: 0,
            recompile_preparing: false,
            view: None,
        }
    }

/// Open a transaction against the current world and run one attempt to
/// completion. Returns the attempt's
/// [`LiveSnapshot`], to be released only after the commit reply, or
/// `None` for a joiner.
async fn open_attempt(
    &mut self,
    tx: &flume::Sender<CommitProtocol>,
) -> Result<Option<LiveSnapshot>> {
    let live = if self.joins_parent {
        None
    } else {
        Some(start_txn(tx).await?)
    };

    if let Some(live) = &live {
        self.context.txn = TxnHandle::new(Transaction::new(live.inner.clone()));
        self.context.clear_commands();
    }

    let seed = self
        .seed
        .clone()
        .expect("top-level attempt has a seed; joiners never open");

    if live.is_some() {
        self.context
            .txn
            .with(|txn| txn.set_origin(&seed.process, seed.entry.name()));
    }

    self.reset();
    self.stack.cleanup_target =
        matches!(seed.entry, SeedEntry::CleanUp).then(|| seed.process.clone());

    if live.is_some() && matches!(seed.entry, SeedEntry::SystemInitializer(_)) {
        let space = self.context.object_space();
        if space.is_system_key(&space.process_key(&seed.process))
            && !seed.process.is_initialized(&self.context.txn)
        {
            self.context.insert_process_transactional(&seed.process);
        }
    }

    // Claimed inside the attempt, so a rejected initialization re-runs
    // instead of staying marked.
    if seed.initializes && !seed.process.claim_init(&self.context.txn) {
        return Ok(live);
    }

    let result = {
        let mut running = RunningTask {
            task: self,
            finished: false,
        };
        let result = running.task.run_entry(&seed).await;
        running.finished = true;
        result
    };
    if let Err(e) = result {
        // A failed run holds nothing the committer needs.
        drop(live);
        return Err(e);
    }

    Ok(live)
}

async fn request<R: Send + 'static>(
    tx: &flume::Sender<CommitProtocol>,
    message: impl FnOnce(flume::Sender<R>) -> CommitProtocol,
) -> Result<R> {
    let (reply_tx, reply_rx) = flume::bounded(1);
    tx.send(message(reply_tx))
        .map_err(|_| -> lpc_rs_errors::LpcError { lpc_error!("committer channel closed") })?;
    reply_rx
        .recv_async()
        .await
        .map_err(|_| -> lpc_rs_errors::LpcError { lpc_error!("no reply from committer") })
}

/// Start a transaction against the committer's current world and hand back
/// the release handle.
pub(crate) async fn start_txn(tx: &flume::Sender<CommitProtocol>) -> Result<LiveSnapshot> {
    request(tx, |reply| CommitProtocol::Start { reply }).await
}

CommitProtocol::Start { reply } => {
    // Count before hand-out: a failed reply drops the
    // LiveSnapshot, which self-releases.
    *self
        .live_versions
        .entry(self.snapshot.version())
        .or_insert(0) += 1;
    let live_snapshot = LiveSnapshot::new(self.snapshot.clone(), tx.clone());
    reply.send(live_snapshot).unwrap_or_else(|e| {
        error!("Failed to send live snapshot: {e}");
        self.stats.reply_failure()
    });
}

async fn begin_attempt(
    &mut self,
    tx: &flume::Sender<CommitProtocol>,
) -> Result<Option<LiveSnapshot>> {
    let live = start_txn(tx).await?;
    let mut template = self.template.clone();
    template.txn = TxnHandle::new(Transaction::new(live.inner.clone()));
    template
        .txn
        .with(|txn| txn.set_origin(&self.actor, "command"));
    template.set_this_player(Some(self.actor.clone()));
    let ctx = template.into_task_context(self.actor.clone());
    let ctx = self.context.insert(ctx);
    match dispatch_from_connection(ctx, self.actor.clone(), &self.line).await {
        Ok(outcome) => {
            self.outcome = outcome;
            Ok(Some(live))
        }
        Err(e) => {
            // A failed attempt holds nothing the committer needs.
            drop(live);
            Err(e)
        }
    }
}

/// Execute an owner or joiner within its original evaluation allowance.
pub(crate) async fn run<B: AttemptBody>(&self, body: &mut B) -> (Result<()>, RetryStats) {
    self.execute(body, &self.telemetry).await
}

async fn execute<B: AttemptBody>(
    &self,
    body: &mut B,
    telemetry: &AttemptTelemetry,
) -> (Result<()>, RetryStats) {
    let started = std::time::Instant::now();
    let owning = !body.is_nested();
    let timeout_ms = body.timeout_ms();
    let deadline =
        (timeout_ms != 0).then(|| Instant::now() + Duration::from_millis(timeout_ms));
    let mut attempts = 0u64;
    let mut conflicts = 0u64;
    let mut phases = PhaseTimes::default();
    let mut admission = AdmissionStats::default();
    let mut last_conflict = None;
    let mut retry_cell = None;
    let mut backoff = match self.commit_watch.clone() {
        Some(watch) => Backoff::watching(watch),
        None => Backoff::new(),
    };

    let mut result = loop {
        if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
            break Err(attempt_timeout(body, attempts, conflicts));
        }
        let turn = if let Some(cell) = retry_cell.take() {
            let waiting = Instant::now();
            let acquired = match deadline {
                Some(deadline) => timeout_at(deadline, self.admission.acquire(cell)).await,
                None => Ok(self.admission.acquire(cell).await),
            };
            admission.waited += waiting.elapsed();
            match acquired {
                Ok(Ok(turn)) => {
                    admission.acquisitions += 1;
                    if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
                        admission.timeouts += 1;
                        break Err(attempt_timeout(body, attempts, conflicts));
                    }
                    Some(turn)
                }
                Ok(Err(error)) => break Err(error),
                Err(_) => {
                    admission.timeouts += 1;
                    break Err(attempt_timeout(body, attempts, conflicts));
                }
            }
        } else {
            None
        };
        attempts += 1;

        let attempt_started = Instant::now();
        let attempt = match deadline {
            Some(deadline) => match timeout_at(deadline, body.begin_attempt(&self.tx)).await {
                Ok(attempt) => attempt,
                Err(_) => Err(attempt_timeout(body, attempts, conflicts)),
            },
            None => body.begin_attempt(&self.tx).await,
        };
        phases.attempt += attempt_started.elapsed();
        if owning {
            phases.compilation += body.take_compilation_time();
        }
        let live = match attempt {
            Ok(live) => live,
            Err(e) => break Err(e),
        };

        let Some(mut live) = live else {
            break Ok(());
        };

        // The commit releases the pin, including when its reply crosses the deadline.
        live.disarm();
        let commit_started = Instant::now();
        let committed = body.commit_phase(&self.tx, live).await;
        phases.commit += commit_started.elapsed();
        drop(turn);
        let (commit, effects) = match committed {
            Ok(c) => c,
            Err(e) => break Err(e),
        };

        match commit {
            Ok(()) => {
                let delivery_started = Instant::now();
                let delivered = body.deliver(effects).await;
                phases.delivery += delivery_started.elapsed();
                break delivered;
            }
            Err(conflict) => {
                conflicts += 1;
                if owning && let Conflict::ReadInvalidated { cell, .. } = &conflict {
                    retry_cell = Some(*cell);
                }
                last_conflict = Some(conflict);
            }
        }
        if retry_cell.is_none() {
            match deadline {
                Some(deadline) => {
                    if timeout_at(deadline, backoff.stagger(conflicts))
                        .await
                        .is_err()
                    {
                        break Err(attempt_timeout(body, attempts, conflicts));
                    }
                }
                None => backoff.stagger(conflicts).await,
            }
        }
    };

    let stats = RetryStats {
        attempts,
        conflicts,
        duration: started.elapsed(),
        backoff: backoff.spent(),
        phases,
        last_conflict,
        admission,
    };
    telemetry.record(&stats, result.is_err(), owning);
    if owning && (result.is_err() || stats.conflicts > 0) {
        if let Err(error) = result {
            let summary = diagnostic_summary(body, &stats);
            tracing::warn!(target: "lpc_rs::transactions", diagnostic = %summary, error = %error, "Transaction failed");
            result = Err(error.with_note(summary));
        } else if tracing::enabled!(target: "lpc_rs::transactions", tracing::Level::DEBUG) {
            tracing::debug!(target: "lpc_rs::transactions", diagnostic = %diagnostic_summary(body, &stats), "Transaction committed after retries");
        }
    }
    (result, stats)
}

async fn begin_attempt(
    &mut self,
    tx: &flume::Sender<CommitProtocol>,
) -> Result<Option<LiveSnapshot>> {
    self.open_attempt(tx).await
}

async fn commit_phase(
    &mut self,
    tx: &flume::Sender<CommitProtocol>,
    _live: LiveSnapshot,
) -> Result<(
    std::result::Result<(), crate::interpreter::stm::Conflict>,
    Vec<Effect>,
)> {
    // Clone the changeset, not take it: the result's payload is read
    // through this handle after the commit, against the pre-commit
    // snapshot plus this changeset.
    let changeset = self.context.txn.with(|t| t.clone_changeset());
    let commit = commit_changeset(tx, changeset).await?;
    let effects = self.context.txn.with(|t| t.take_effects());
    Ok((commit, effects))
}

async fn deliver(&mut self, effects: Vec<Effect>) -> Result<()> {
    if !effects.is_empty() {
        flush_effects(&self.context.global_state, effects).await;
    }
    Ok(())
}

