/// The committer's lifetime commit totals; for bench measurement and tooling, not the hot path.
pub(crate) async fn committer_stats(tx: &flume::Sender<CommitProtocol>) -> Result<CommitterStats> {
    request(tx, |reply| CommitProtocol::Stats { reply }).await
}

/// Commit a changeset from a disarmed attempt and await the reply; the
/// commit carries the release of the base version's pin. `Ok(())` =
/// committed; `Ok(Err(Conflict))` = rejected.
pub(crate) async fn commit_changeset(
    tx: &flume::Sender<CommitProtocol>,
    changeset: Changeset,
) -> Result<std::result::Result<(), Conflict>> {
    request(tx, |reply| CommitProtocol::Commit {
        changeset,
        releases_base: true,
        reply,
    })
    .await
}

CommitProtocol::Commit {
    changeset,
    releases_base,
    reply,
} => {
    let started = std::time::Instant::now();
    let base = changeset.base_version();
    let result = self.commit(changeset);
    if releases_base {
        self.release(base);
    }
    if self.live_versions.is_empty() {
        self.evict_old_versions();
    }
    reply.send(result).unwrap_or_else(|e| {
        error!("Failed to send commit result: {e}");
        self.stats.reply_failure()
    });
    self.stats.commit_service_ns += started.elapsed().as_nanos() as u64;
}

    pub(crate) fn commit(&mut self, mut changeset: Changeset) -> Result<(), Conflict> {
        let current_version = self.snapshot.version();
        let changeset_version = changeset.base_version();

        // Should not occur in practice - it implies versions are being created in more than one place.
        if current_version < changeset_version {
            self.stats.conflict();
            return Err(Conflict::FutureVersion {
                base: changeset_version,
                current: current_version,
            });
        }

        // changeset's base evicted → not enough history to resolve the conflict rule
        if changeset_version < self.oldest_retained {
            self.stats.conflict();
            return Err(Conflict::HistoryUnavailable {
                base: changeset_version,
                oldest: self.oldest_retained,
                current: current_version,
            });
        }

        // check the conflict rule
        for (version, written) in self
            .write_history
            .range(changeset_version..=current_version)
        {
            if *version == changeset_version {
                continue;
            }

            self.stats.validation_scanned_versions += 1;
            if let Some(cell) = changeset.conflicting_read(&written.vars) {
                self.stats.conflict();
                return Err(Conflict::ReadInvalidated {
                    cell,
                    base: changeset_version,
                    current: current_version,
                    written_at: *version,
                    writer: written.origin.clone(),
                });
            }
        }

        // The merges fold onto the committed values here, where a type
        // mismatch rejects the whole changeset before anything applies.
        if let Err(cell) = changeset.fold_merges(|var_id| self.snapshot.peek(var_id).cloned()) {
            self.stats.conflict();
            return Err(Conflict::MergeMismatch {
                cell,
                base: changeset_version,
                current: current_version,
            });
        }

        self.publish(changeset, true);
        Ok(())
    }

    fn publish(&mut self, mut changeset: Changeset, transaction: bool) {
        let mut written_vars = changeset.touched_vars();
        if !changeset.object_changes.is_empty() {
            written_vars.insert(self.snapshot.object_membership);
        }
        if written_vars.is_empty() {
            // Conflict-free read-only changeset: no new version, no history.
            self.stats.read_only_commit();
            return;
        }

        let new_version = Version::new();
        let origin = changeset.origin.clone();
        let publications = std::mem::take(&mut changeset.system_publications);
        let socket_publications = std::mem::take(&mut changeset.socket_publications);
        let new_snapshot = self.snapshot.apply(new_version, changeset);
        self.snapshot = new_snapshot;
        for publication in publications {
            publication.apply();
        }
        for publication in socket_publications {
            publication.apply();
        }

        // Keep history insert after the snapshot apply, else a problem in apply leads to
        // all transactions conflicting in the future.
        self.write_history.insert(
            new_version,
            CommittedWrite {
                vars: written_vars,
                origin,
            },
        );
        if transaction {
            self.stats.commit();
        }
        self.commit_watch.send_replace(new_version);
    }
}
